#include "portal_routes.h"
#include "portal_page_logic.h"
#include "wifi_manager.h"
#include "../config/constants.h"
#include <esp_http_server.h>
#include <string.h>
#include "portal_page_data.h"  // generated by tools/build-scripts/embed_portal.py into the build directory

static_assert(PORTAL_PAGE_GZ_SIZE > 0 && PORTAL_PAGE_GZ_SIZE <= PORTAL_PAGE_BUDGET_BYTES,
              "embedded web panel page exceeds PORTAL_PAGE_BUDGET_BYTES");

namespace {

enum class HeaderRead : uint8_t { ABSENT, OK, OVERSIZE };

// Reads a request header into out. A value that does not fit is OVERSIZE (never silently truncated).
HeaderRead read_header(httpd_req_t* req, const char* name, char* out, size_t capacity) {
    out[0] = '\0';
    const size_t length = httpd_req_get_hdr_value_len(req, name);
    if (length == 0) return HeaderRead::ABSENT;
    if (length >= capacity) return HeaderRead::OVERSIZE;
    return httpd_req_get_hdr_value_str(req, name, out, capacity) == ESP_OK ? HeaderRead::OK : HeaderRead::ABSENT;
}

const char* status_line(int status) {
    switch (status) {
        case 200: return "200 OK";
        case 400: return "400 Bad Request";
        case 403: return "403 Forbidden";
        case 409: return "409 Conflict";
        case 413: return "413 Payload Too Large";
        case 415: return "415 Unsupported Media Type";
        case 500: return "500 Internal Server Error";
        case 503: return "503 Service Unavailable";
        default: return "500 Internal Server Error";
    }
}

// Headers every page reply carries (200 and 304)
void set_page_headers(httpd_req_t* req, const char* etag) {
    httpd_resp_set_hdr(req, "ETag", etag);
    httpd_resp_set_hdr(req, "Cache-Control", "no-cache");  // revalidate: a new firmware shows its new page
    httpd_resp_set_hdr(req, "X-Content-Type-Options", "nosniff");
    httpd_resp_set_hdr(req, "Referrer-Policy", "no-referrer");
    httpd_resp_set_hdr(req, "Content-Security-Policy", PORTAL_PAGE_CSP);
    httpd_resp_set_hdr(req, "Connection", "close");
}

}  // namespace

PortalError portal_route_admit(httpd_req* req, PortalRoute route) {
    if (!portal_route_enabled(route, wifi_manager.web_enabled(), wifi_manager.push_enabled())) {
        return portal_route_refusal(route);
    }

    char host[PORTAL_HEADER_MAX_LEN + 1];
    char origin[PORTAL_HEADER_MAX_LEN + 1];
    char content_type[PORTAL_HEADER_MAX_LEN + 1];
    char custom[PORTAL_HEADER_MAX_LEN + 1];
    const HeaderRead host_read = read_header(req, "Host", host, sizeof(host));
    const HeaderRead origin_read = read_header(req, "Origin", origin, sizeof(origin));
    const HeaderRead type_read = read_header(req, "Content-Type", content_type, sizeof(content_type));
    const HeaderRead custom_read = read_header(req, PORTAL_CUSTOM_HEADER_NAME, custom, sizeof(custom));

    // An oversize value is handed to the pure guards as something they refuse (empty Host, a non-http Origin)
    PortalRequestHeaders headers;
    headers.host = host_read == HeaderRead::OK ? host : (host_read == HeaderRead::OVERSIZE ? "" : nullptr);
    headers.origin = origin_read == HeaderRead::OK ? origin : (origin_read == HeaderRead::OVERSIZE ? "oversize" : nullptr);
    headers.content_type = type_read == HeaderRead::OK ? content_type : (type_read == HeaderRead::OVERSIZE ? "oversize" : nullptr);
    headers.custom = custom_read == HeaderRead::OK ? custom : (custom_read == HeaderRead::OVERSIZE ? "oversize" : nullptr);

    const bool state_changing = route == PortalRoute::API_WRITE || route == PortalRoute::API_COMMAND;
    return portal_check_request(headers, state_changing);
}

int portal_send_error(httpd_req* req, PortalError error) {
    const PortalErrorInfo& info = portal_error_info(error);
    char json[256];
    portal_encode_error(error, json, sizeof(json));
    httpd_resp_set_status(req, status_line(info.status));
    httpd_resp_set_type(req, "application/json");
    httpd_resp_set_hdr(req, "Cache-Control", "no-store");
    httpd_resp_send(req, json, HTTPD_RESP_USE_STRLEN);
    return ESP_FAIL;
}

int portal_handle_page(httpd_req* req) {
    const PortalError refused = portal_route_admit(req, PortalRoute::PAGE);
    if (refused != PortalError::NONE) return portal_send_error(req, refused);

    char etag[PORTAL_PAGE_ETAG_MAX_LEN];
    portal_page_etag(BUILD_NUMBER, PORTAL_PAGE_GZ_CRC32, etag, sizeof(etag));

    char if_none_match[PORTAL_PAGE_ETAG_MAX_LEN * 2];
    if (read_header(req, "If-None-Match", if_none_match, sizeof(if_none_match)) == HeaderRead::OK &&
        portal_etag_matches(if_none_match, etag)) {
        httpd_resp_set_status(req, "304 Not Modified");
        set_page_headers(req, etag);
        httpd_resp_send(req, nullptr, 0);
        return ESP_OK;
    }

    httpd_resp_set_type(req, "text/html; charset=utf-8");
    httpd_resp_set_hdr(req, "Content-Encoding", "gzip");
    set_page_headers(req, etag);
    return httpd_resp_send(req, reinterpret_cast<const char*>(portal_page_gz), PORTAL_PAGE_GZ_SIZE);
}
